-- =====================================================================
-- RipassoAI — 0005: 30 domande per HTML e per CSS
--   HTML: 2 già presenti + 28 nuove
--   CSS:  3 già presenti + 27 nuove
-- =====================================================================

select public.importa_quiz('html', $j$[
  {"livello":"L1","testo":"Quale elemento definisce il titolo più importante della pagina?","spiegazione":"h1 è il titolo principale; va usato una sola volta per pagina e descrive il contenuto.","opzioni":["h1","h2","header","title"],"corretta":0},
  {"livello":"L1","testo":"Quale elemento contiene i metadati non visibili della pagina?","spiegazione":"head raccoglie title, meta, link e script; il suo contenuto non viene mostrato nel body.","opzioni":["head","body","header","main"],"corretta":0},
  {"livello":"L1","testo":"Quale attributo dichiara la lingua del documento?","spiegazione":"lang sull'elemento html permette a screen reader e traduttori di pronunciare correttamente il testo.","opzioni":["lang","dir","translate","locale"],"corretta":0},
  {"livello":"L1","testo":"Quale elemento crea un collegamento ipertestuale?","spiegazione":"a con href crea il link; senza href non è raggiungibile da tastiera come link.","opzioni":["a","link","nav","href"],"corretta":0},
  {"livello":"L1","testo":"Quale elemento crea un elenco senza un ordine significativo?","spiegazione":"ul è l'elenco non ordinato; ol si usa quando la sequenza conta.","opzioni":["ul","ol","dl","li"],"corretta":0},
  {"livello":"L1","testo":"Quale elemento inserisce un'immagine nella pagina?","spiegazione":"img è un elemento vuoto: richiede src e alt, non ha tag di chiusura.","opzioni":["img","picture","figure","image"],"corretta":0},
  {"livello":"L1","testo":"Quale elemento definisce una cella di intestazione di una tabella?","spiegazione":"th identifica l'intestazione di colonna o riga e aiuta gli screen reader ad associare i dati.","opzioni":["th","td","tr","thead"],"corretta":0},
  {"livello":"L1","testo":"Quale elemento raccoglie i controlli per l'invio di dati?","spiegazione":"form raggruppa i campi e definisce action e method dell'invio.","opzioni":["form","fieldset","input","section"],"corretta":0},
  {"livello":"L1","testo":"Quale elemento crea un campo di testo multilinea?","spiegazione":"textarea accetta più righe; input invece è a riga singola.","opzioni":["textarea","input type=\"text\"","output","pre"],"corretta":0},
  {"livello":"L1","testo":"Quale elemento associa un'etichetta a un controllo del form?","spiegazione":"label migliora l'accessibilità: il click sull'etichetta porta il focus al campo collegato.","opzioni":["label","legend","span","caption"],"corretta":0},

  {"livello":"L2","testo":"Perché ogni section dovrebbe avere un heading?","spiegazione":"Un titolo rende la sezione riconoscibile nella mappa del documento e nella navigazione assistiva.","opzioni":["Perché una sezione senza titolo non è una regione riconoscibile","Perché il CSS non applica lo stile senza heading","Perché il browser rifiuta la sezione","Perché serve per la validazione del form"],"corretta":0},
  {"livello":"L2","testo":"Qual è la differenza tra article e section?","spiegazione":"article è un contenuto autonomo e distribuibile, section raggruppa contenuti correlati con un titolo.","opzioni":["article è autonomo e riutilizzabile, section raggruppa contenuti correlati","Sono sinonimi","section è solo per le immagini","article si usa solo nei form"],"corretta":0},
  {"livello":"L2","testo":"A cosa serve l'attributo for di label?","spiegazione":"for deve contenere l'id del controllo: crea l'associazione logica tra etichetta e campo.","opzioni":["Collega l'etichetta al controllo tramite il suo id","Definisce il nome del campo inviato","Imposta il placeholder","Indica il tipo di input"],"corretta":0},
  {"livello":"L2","testo":"Perché nav non va usato per qualsiasi elenco di link?","spiegazione":"nav identifica la navigazione principale: usarlo ovunque crea molte regioni inutili per gli screen reader.","opzioni":["Perché crea regioni di navigazione inutili per gli screen reader","Perché nav non accetta elenchi","Perché non è supportato dai browser","Perché impedisce il CSS"],"corretta":0},
  {"livello":"L2","testo":"Cosa attiva l'attributo required su un input?","spiegazione":"Il browser blocca l'invio se il campo è vuoto: è una validazione nativa, da ripetere comunque lato server.","opzioni":["La validazione nativa che impedisce l'invio se vuoto","Il focus automatico sul campo","Il salvataggio automatico","La crittografia del valore"],"corretta":0},
  {"livello":"L2","testo":"Quale tipo di input valida automaticamente un indirizzo email?","spiegazione":"type email attiva la tastiera adatta e la validazione del formato; il server deve riverificare.","opzioni":["type=\"email\"","type=\"text\"","type=\"url\"","type=\"search\""],"corretta":0},
  {"livello":"L2","testo":"Perché un button dentro un form dovrebbe dichiarare type?","spiegazione":"Il default è submit: un pulsante che non deve inviare va marcato type=\"button\".","opzioni":["Perché il default è submit e invierebbe il form","Perché senza type non è cliccabile","Perché Bootstrap lo richiede","Perché altrimenti non riceve il focus"],"corretta":0},
  {"livello":"L2","testo":"Cosa comunica alt=\"\" a uno screen reader?","spiegazione":"Un alt vuoto dichiara l'immagine decorativa, che quindi viene ignorata senza perdere informazione.","opzioni":["Che l'immagine è decorativa e va ignorata","Che manca la descrizione","Che l'immagine è un link","Che l'immagine va scaricata"],"corretta":0},

  {"livello":"L3","testo":"Perché non si dovrebbe saltare un livello di heading?","spiegazione":"La gerarchia h1-h6 costruisce l'indice del documento: saltare livelli confonde la navigazione assistiva.","opzioni":["Perché la gerarchia è l'indice del documento e va rispettata","Perché il browser applica stili errati","Perché il testo diventa illeggibile","Perché la pagina non viene indicizzata"],"corretta":0},
  {"livello":"L3","testo":"Perché usare una tabella per il layout è un problema di accessibilità?","spiegazione":"Le tabelle comunicano relazioni tra righe e colonne: usarle per impaginare crea una struttura falsa.","opzioni":["Crea relazioni riga-colonna inesistenti per gli screen reader","Perché le tabelle non supportano il responsive","Perché occupano troppa memoria","Perché non si possono stilizzare"],"corretta":0},
  {"livello":"L3","testo":"Quale vantaggio offre details con summary rispetto a un accordion in JavaScript?","spiegazione":"L'espansione è nativa, accessibile e funziona anche senza JavaScript.","opzioni":["Funziona senza JavaScript ed è accessibile nativamente","Permette animazioni più veloci","Riduce il peso delle immagini","Supporta le API di rete"],"corretta":0},
  {"livello":"L3","testo":"Perché una finestra dialog richiede una gestione esplicita del focus?","spiegazione":"Il focus deve restare dentro il modale e tornare al pulsante che l'ha aperto alla chiusura.","opzioni":["Perché il focus deve restare nel modale e tornare al trigger","Perché dialog non supporta la tastiera","Perché il focus rompe il layout","Perché altrimenti la pagina si ricarica"],"corretta":0},
  {"livello":"L3","testo":"Perché l'attributo lang è importante per gli screen reader?","spiegazione":"Indica la lingua di pronuncia: senza lang il motore vocale può leggere con la fonetica sbagliata.","opzioni":["Determina la pronuncia corretta del testo","Imposta la codifica dei caratteri","Traduce automaticamente la pagina","Definisce la direzione del testo"],"corretta":0},
  {"livello":"L3","testo":"Perché un'immagine dentro figure dovrebbe avere figcaption?","spiegazione":"La didascalia è associata semanticamente alla figura e descrive il contesto, non solo il contenuto.","opzioni":["Perché la didascalia viene associata semanticamente alla figura","Perché senza caption l'immagine non si carica","Perché il browser richiede due testi alternativi","Perché migliora la compressione"],"corretta":0},
  {"livello":"L3","testo":"Perché usare time con l'attributo datetime?","spiegazione":"datetime espone una data leggibile dalle macchine, utile a calendari, feed e assistenti.","opzioni":["Per fornire una data leggibile dalle macchine","Per formattare la data in italiano","Per aggiungere un timer alla pagina","Per validare il campo data"],"corretta":0},

  {"livello":"L4","testo":"Un form ha due pulsanti submit senza attributo name: quale problema nasce?","spiegazione":"Il server riceve la stessa richiesta e non sa quale pulsante è stato premuto: serve name/value distintivo.","opzioni":["Il server non distingue quale pulsante è stato premuto","Il form non viene inviato","Il browser blocca il secondo pulsante","Il CSS applica lo stile sbagliato"],"corretta":0},
  {"livello":"L4","testo":"Perché il markup semantico aiuta anche SEO e strumenti automatici?","spiegazione":"Una struttura esplicita permette di identificare contenuto principale, sezioni e relazioni senza indovinare.","opzioni":["Rende contenuto e relazioni interpretabili senza euristiche","Aumenta la velocità del server","Riduce il numero di richieste HTTP","Sostituisce i dati strutturati"],"corretta":0},
  {"livello":"L4","testo":"Perché il placeholder non sostituisce label?","spiegazione":"Sparisce alla digitazione, ha basso contrasto e non è letto in modo affidabile: l'etichetta persistente è obbligatoria.","opzioni":["Sparisce alla digitazione e non è un'etichetta affidabile","Perché il placeholder è deprecato","Perché non supporta l'italiano","Perché blocca l'autocomplete"],"corretta":0}
]$j$::jsonb);

select public.importa_quiz('css', $j$[
  {"livello":"L1","testo":"Quale proprietà imposta il colore del testo?","spiegazione":"color agisce sul testo; background-color agisce sullo sfondo.","opzioni":["color","background-color","fill","text-color"],"corretta":0},
  {"livello":"L1","testo":"Quale proprietà imposta lo spazio esterno a un elemento?","spiegazione":"margin è lo spazio fuori dal bordo; padding è quello interno.","opzioni":["margin","padding","border","outline"],"corretta":0},
  {"livello":"L1","testo":"Quale unità è relativa alla dimensione del font radice?","spiegazione":"rem si basa sul font di html e rispetta le preferenze dell'utente.","opzioni":["rem","px","pt","vh"],"corretta":0},
  {"livello":"L1","testo":"Quale proprietà arrotonda gli angoli di un elemento?","spiegazione":"border-radius accetta uno o più raggi, anche in percentuale per ottenere un cerchio.","opzioni":["border-radius","corner-style","border-style","outline-radius"],"corretta":0},
  {"livello":"L1","testo":"Quale valore di display dispone i figli su un asse?","spiegazione":"display flex attiva Flexbox: direzione, allineamento e distribuzione si controllano con le proprietà flex.","opzioni":["flex","block","inline","table"],"corretta":0},
  {"livello":"L1","testo":"Quale proprietà imposta un'immagine di sfondo?","spiegazione":"background-image accetta url(); il colore di fallback va su background-color.","opzioni":["background-image","background-color","border-image","content"],"corretta":0},
  {"livello":"L1","testo":"Quale selettore indica un elemento tramite id?","spiegazione":"#id seleziona l'elemento con quell'id, che deve essere unico nella pagina.","opzioni":["#id",".id","id()","*id"],"corretta":0},
  {"livello":"L1","testo":"Quale proprietà controlla la dimensione del testo?","spiegazione":"font-size accetta unità relative o assolute; con rem rispetta lo zoom dell'utente.","opzioni":["font-size","font-weight","line-height","text-size"],"corretta":0},

  {"livello":"L2","testo":"Qual è la differenza tra margin e padding?","spiegazione":"margin separa l'elemento dagli altri, padding separa il contenuto dal bordo.","opzioni":["margin è esterno al bordo, padding interno","Sono la stessa cosa","margin vale solo per il testo","padding non accetta valori negativi"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa display: none?","spiegazione":"Rimuove l'elemento dal layout: non occupa spazio e non viene letto dagli screen reader.","opzioni":["Rimuove l'elemento dal layout e dall'accessibilità","Nasconde l'elemento ma riserva lo spazio","Rende l'elemento trasparente","Sposta l'elemento fuori schermo"],"corretta":0},
  {"livello":"L2","testo":"Qual è la differenza tra display none e visibility hidden?","spiegazione":"none toglie l'elemento dal flusso, hidden lo rende invisibile ma conserva il suo spazio.","opzioni":["none toglie dal flusso, hidden conserva lo spazio","Sono identici","hidden toglie dal flusso, none lo conserva","visibility è deprecato"],"corretta":0},
  {"livello":"L2","testo":"Come si comporta position: sticky?","spiegazione":"Si comporta come relative finché non raggiunge la soglia, poi resta agganciato dentro il contenitore.","opzioni":["Relative finché non raggiunge la soglia, poi resta agganciato","Sempre fisso rispetto al viewport","Sempre assoluto rispetto al body","Non accetta top e left"],"corretta":0},
  {"livello":"L2","testo":"Cosa controlla z-index?","spiegazione":"Ordina la sovrapposizione tra elementi posizionati o con stacking context.","opzioni":["L'ordine di sovrapposizione tra elementi posizionati","La larghezza del bordo","La profondità 3D del testo","La priorità dei media query"],"corretta":0},
  {"livello":"L2","testo":"Qual è la differenza tra em e rem?","spiegazione":"em dipende dal font dell'elemento o del genitore, rem dal font radice di html.","opzioni":["em dipende dal contesto, rem dalla radice","rem dipende dal contesto, em dalla radice","Sono identici","em vale solo per i margini"],"corretta":0},
  {"livello":"L2","testo":"A cosa serve una media query?","spiegazione":"Applica blocchi di stili quando cambiano viewport o caratteristiche del dispositivo.","opzioni":["Ad applicare stili condizionati a viewport o preferenze","A caricare immagini più grandi","A ridurre il numero di CSS","A eseguire JavaScript"],"corretta":0},

  {"livello":"L3","testo":"Perché per i font si preferisce rem alle px?","spiegazione":"rem rispetta la dimensione del font scelta dall'utente e lo zoom, migliorando l'accessibilità.","opzioni":["Rispetta le preferenze di dimensione del font dell'utente","È più veloce da calcolare","Riduce il peso del CSS","Evita i media query"],"corretta":0},
  {"livello":"L3","testo":"Perché usare :focus-visible invece di :focus?","spiegazione":"Mostra l'anello di focus solo quando serve, cioè nella navigazione da tastiera.","opzioni":["Mostra l'anello solo quando il focus arriva da tastiera","Elimina il focus da tutti gli elementi","Funziona solo su mobile","Sostituisce :hover"],"corretta":0},
  {"livello":"L3","testo":"Perché il margin collapse può sorprendere?","spiegazione":"I margini verticali adiacenti si fondono nel maggiore, quindi lo spazio non è la loro somma.","opzioni":["I margini verticali adiacenti si fondono nel maggiore","I margini orizzontali si annullano","Il padding diventa margin","Il bordo raddoppia"],"corretta":0},
  {"livello":"L3","testo":"Rispetto a cosa si posiziona un elemento absolute?","spiegazione":"Al primo antenato posizionato; se non esiste, al blocco iniziale del documento.","opzioni":["Al primo antenato posizionato, altrimenti al blocco iniziale","Sempre al viewport","Sempre al genitore diretto","Sempre al body"],"corretta":0},
  {"livello":"L3","testo":"Perché flex-basis non coincide sempre con la larghezza finale?","spiegazione":"Entrano in gioco flex-grow, flex-shrink e la dimensione minima del contenuto.","opzioni":["Perché grow, shrink e min-content possono modificarla","Perché flex-basis è ignorato","Perché vale solo in verticale","Perché dipende dal font"],"corretta":0},
  {"livello":"L3","testo":"Perché grid-template-columns: 1fr 1fr è meglio di 50% 50% con un gap?","spiegazione":"fr distribuisce lo spazio rimanente dopo il gap; con 50% più gap si supera il 100% e appare lo scroll.","opzioni":["fr tiene conto del gap, 50% più gap supera il contenitore","Sono equivalenti","1fr è supportato solo su mobile","50% non accetta gap"],"corretta":0},
  {"livello":"L3","testo":"Perché abusare di !important è rischioso?","spiegazione":"Rompe la cascata: diventa difficile sovrascrivere lo stile e capire l'ordine delle regole.","opzioni":["Rompe la cascata e rende difficile sovrascrivere","Rallenta il rendering","Non è supportato da Bootstrap","Impedisce il responsive"],"corretta":0},
  {"livello":"L3","testo":"Cosa causa un overflow orizzontale indesiderato?","spiegazione":"Tipicamente larghezze fisse con padding senza border-box, 100vw o elementi più larghi del contenitore.","opzioni":["Larghezze fisse con padding, 100vw o elementi troppo larghi","L'uso di rem","I media query","I bordi arrotondati"],"corretta":0},

  {"livello":"L4","testo":"Perché il contrasto del testo è un requisito e non una scelta estetica?","spiegazione":"Le linee guida WCAG impongono rapporti minimi per garantire leggibilità a ipovedenti e in condizioni di luce scarsa.","opzioni":["Perché WCAG impone rapporti minimi di contrasto","Perché i colori scuri consumano meno batteria","Perché il contrasto riduce il peso delle immagini","Perché i browser lo calcolano automaticamente"],"corretta":0},
  {"livello":"L4","testo":"Perché le animazioni dovrebbero rispettare prefers-reduced-motion?","spiegazione":"Alcuni utenti soffrono di disturbi vestibolari: il movimento va ridotto o eliminato su richiesta.","opzioni":["Perché il movimento può causare disturbi vestibolari","Perché consuma CPU","Perché non è supportato su Safari","Perché rallenta il caricamento"],"corretta":0},
  {"livello":"L4","testo":"Perché height 100vh può tagliare contenuti su mobile?","spiegazione":"Le barre dinamiche del browser cambiano l'altezza visibile: vh non le segue, dvh sì.","opzioni":["Perché vh non segue le barre dinamiche del browser, dvh sì","Perché vh è deprecato","Perché il mobile non supporta vh","Perché manca un media query"],"corretta":0},
  {"livello":"L4","testo":"Perché gli stili inline rendono la manutenzione difficile?","spiegazione":"Hanno specificità alta, non si riusano e non possono essere sovrascritti facilmente da un foglio esterno.","opzioni":["Hanno specificità alta e non sono riutilizzabili","Non sono supportati dai browser","Impediscono il caricamento del CSS","Bloccano il rendering"],"corretta":0}
]$j$::jsonb);
